import os, re, glob, collections
R = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
out = ['# 01 - Legacy inventory (generated from the repository)\n',
       'Generated by scanning `app/` (core application only; optional modules are listed at the end). '
       'Regenerate with `python3 modernization/tools/gen_inventory.py` if the legacy sources change.\n']
csd = open(f'{R}/app/csd/CARDDEMO.CSD', errors='replace').read()
trans = re.findall(r'DEFINE TRANSACTION\((\w+)\).*?PROGRAM\((\w+)\)', csd, re.S)
progs_map = {}
for b in glob.glob(f'{R}/app/bms/*.bms'):
    progs_map[os.path.basename(b)[:-4].upper()] = True
def first_comment(path):
    for line in open(path, errors='replace'):
        m = re.match(r'.{6}\*\s*(?:Function|FUNCTION)\s*:?\s*(.+)', line)
        if m: return m.group(1).strip().rstrip('*').strip()
    return ''
def mapset(prog):
    src = open(f'{R}/app/cbl/{prog}.cbl', errors='replace').read() if os.path.exists(f'{R}/app/cbl/{prog}.cbl') else ''
    m = re.search(r"MAPSET\s*\(\s*'?(\w+)'?\s*\)", src) or re.search(r"LIT-THISMAPSET\s+PIC X\(\d+\)\s+VALUE\s+'(\w+)", src)
    return m.group(1).strip() if m else ''
def files(prog):
    src = open(f'{R}/app/cbl/{prog}.cbl', errors='replace').read() if os.path.exists(f'{R}/app/cbl/{prog}.cbl') else ''
    s = set(re.findall(r"(?:DATASET|FILE)\s*\(\s*'?([\w-]+)'?\s*\)", src))
    s |= set(re.findall(r"VALUE\s+'(ACCTDAT|CARDDAT|CUSTDAT|CXACAIX|CARDAIX|CCXREF|TRANSACT|USRSEC)\s*'", src))
    return ', '.join(sorted(x for x in s if not x.startswith('WS-') and not x.startswith('LIT-')))
out.append('\n## (a) Online CICS transactions\n\n| Transaction | Program | Mapset | Files | Function |\n|---|---|---|---|---|')
for t, p in trans:
    if os.path.exists(f'{R}/app/cbl/{p}.cbl'):
        out.append(f'| {t} | {p} | {mapset(p)} | {files(p)} | {first_comment(f"{R}/app/cbl/{p}.cbl")} |')
out.append(f'\nBMS mapsets in `app/bms`: {", ".join(sorted(os.path.basename(b)[:-4] for b in glob.glob(R + "/app/bms/*.bms")))}')
out.append('\n## (b) Batch JCL jobs\n\n| Job | Steps (PGM) | Description |\n|---|---|---|')
for j in sorted(glob.glob(f'{R}/app/jcl/*.jcl')):
    src = open(j, errors='replace').read()
    steps = re.findall(r'^//(\w+)\s+EXEC\s+(?:PGM=)?(\w+)', src, re.M)
    desc = ''
    for line in src.splitlines():
        m = re.match(r'//\*\s*(.{8,})', line)
        if m and not set(m.group(1).strip()) <= set('*-= ') and 'Copyright' not in line and 'Licensed' not in line and 'Amazon' not in line:
            desc = m.group(1).strip(' *'); break
    out.append(f'| {os.path.basename(j)[:-4]} | {", ".join(f"{s}:{p}" for s, p in steps)} | {desc[:90]} |')
out.append('\n## (c) VSAM datasets and record layouts\n\n'
  '| Dataset (DD) | Type / key | Record | Copybook | Alternate index | Modern table |\n|---|---|---|---|---|---|\n'
  '| ACCTDAT | KSDS, ACCT-ID 9(11) @0 | 300 | CVACT01Y | - | account |\n'
  '| CARDDAT | KSDS, CARD-NUM X(16) @0 | 150 | CVACT02Y | CARDAIX: CARD-ACCT-ID @16 len 11 (non-unique) | card (+ ix_card_acct_id) |\n'
  '| CUSTDAT | KSDS, CUST-ID 9(9) @0 | 500 | CVCUS01Y | - | customer |\n'
  '| CCXREF | KSDS, XREF-CARD-NUM X(16) @0 | 50 | CVACT03Y | CXACAIX: XREF-ACCT-ID @25 len 11 (non-unique) | card_xref (+ ix_card_xref_acct_id) |\n'
  '| TRANSACT | KSDS, TRAN-ID X(16) @0 | 350 | CVTRA05Y | TRANSACT AIX: TRAN-PROC-TS @304 len 26 | card_transaction (+ ix_card_transaction_proc_ts) |\n'
  '| USRSEC | KSDS, SEC-USR-ID X(8) @0 | 80 | CSUSR01Y | - | user_security |\n'
  '| DISCGRP | KSDS, group+type+cat (16) | 50 | CVTRA02Y | - | disclosure_group |\n'
  '| TCATBALF | KSDS, acct+type+cat (17) | 50 | CVTRA01Y | - | tran_cat_balance |\n'
  '| TRANCATG | KSDS, type+cat (6) | 60 | CVTRA04Y | - | transaction_category |\n'
  '| TRANTYPE | KSDS, type (2) | 60 | CVTRA03Y | - | transaction_type |\n'
  '| DALYTRAN | Sequential PS | 350 | CVTRA06Y | - | daily_transaction (staging) |\n'
  '| DALYREJS | Sequential PS (GDG) | 430 | CVTRA06Y + 80-byte trailer | - | daily_transaction_reject |\n'
  '\nField-level offsets are encoded in `modernization/data-migration/.../CopybookLayouts.java` and verified against the sample data by `LegacyDataParityTest`.\n')
out.append('\n## (d) Data flows\n\n```mermaid\nflowchart LR\n  CC00[COSGN00C] -->|USRSEC| MENU{type A/U}\n  MENU -->|A| CA00[COADM01C] --> CU[COUSR00-03C] --> USRSEC[(USRSEC)]\n'
  '  MENU -->|U| CM00[COMEN01C]\n  CM00 --> ACT[COACTVWC/UPC] --> ACCTDAT[(ACCTDAT)] & CUSTDAT[(CUSTDAT)] & CXACAIX[(CCXREF/CXACAIX)]\n'
  '  CM00 --> CRD[COCRDLIC/SLC/UPC] --> CARDDAT[(CARDDAT/CARDAIX)]\n  CM00 --> TRN[COTRN00-02C] --> TRANSACT[(TRANSACT)]\n'
  '  CM00 --> BIL[COBIL00C] --> TRANSACT & ACCTDAT\n  CM00 --> RPT[CORPT00C] -->|TDQ JOBS| TRANREPT\n'
  '  DALYTRAN[(DALYTRAN)] --> POSTTRAN[CBTRN02C] --> TRANSACT & TCATBALF[(TCATBALF)] & ACCTDAT & DALYREJS[(DALYREJS)]\n'
  '  TCATBALF --> INTCALC[CBACT04C] --> TRANSACT & ACCTDAT\n  DISCGRP[(DISCGRP)] --> INTCALC\n'
  '  TRANSACT --> TRANREPT[CBTRN03C] --> REPORT[/report/]\n  TRANSACT --> CREASTMT[CBSTM03A/B] --> STMT[/statements/]\n```\n')
opt = []
for d in sorted(glob.glob(f'{R}/app/app-*')):
    n = collections.Counter(os.path.splitext(f)[1].lower() for _, _, fs in os.walk(d) for f in fs)
    opt.append(f'| {os.path.basename(d)} | ' + ', '.join(f'{k or "(none)"}: {v}' for k, v in n.most_common(6)) + ' |')
out.append('\n## Optional modules (phase 2)\n\n| Module | Files by type |\n|---|---|\n' + '\n'.join(opt) + '\n')
cnt = collections.Counter(os.path.splitext(f)[1].lower() for f in os.listdir(f'{R}/app/cbl'))
out.append(f'\n## Totals (core)\n\nCOBOL programs: {cnt[".cbl"]}, copybooks: {len(os.listdir(R + "/app/cpy"))}, BMS mapsets: {len(glob.glob(R + "/app/bms/*.bms"))}, '
           f'JCL members: {len(glob.glob(R + "/app/jcl/*.jcl"))}, CICS transactions in CSD: {len(trans)}.\n')
open(f'{R}/docs/modernization/01-inventory.md', 'w').write('\n'.join(out))
print(len(trans), 'transactions;', cnt)
